#!/usr/bin/env node
const fs = require('fs');
const path = require('path');

// Read all event files
const eventsDir = '/data/events';
const files = fs.readdirSync(eventsDir).filter(f => f.endsWith('.json')).sort();

console.log(`Found ${files.length} event files`);

async function loadEvents() {
  let successCount = 0;
  let errorCount = 0;

  for (const file of files) {
    try {
      const eventData = fs.readFileSync(path.join(eventsDir, file), 'utf8').trim();
      const event = JSON.parse(eventData);

      // Convert timestamp to proper format
      event.event_ts = new Date(event.event_ts).toISOString();

      const response = await fetch('http://localhost:4000/ingest/ProductEvent', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(event)
      });

      if (response.ok) {
        console.log(`✓ Loaded ${file}: ${event.event_type} event for product ${event.product_id}`);
        successCount++;
      } else {
        console.error(`✗ Failed to load ${file}: ${response.status} ${response.statusText}`);
        errorCount++;
      }

      // Small delay to avoid overwhelming the system
      await new Promise(resolve => setTimeout(resolve, 50));

    } catch (error) {
      console.error(`✗ Error processing ${file}:`, error.message);
      errorCount++;
    }
  }

  console.log(`\nSummary: ${successCount} events loaded successfully, ${errorCount} errors`);
}

loadEvents().catch(console.error);

